template.solver:
def solve(N, k, m):
    best = 0
    for r in range(m):
        nums = [x for x in range(1, N + 1) if x % m == r]
        if len(nums) < k:
            continue
        P = sum(1 for x in nums if x > 1 and all(x % d for d in range(2, floor(sqrt(x)) + 1)))
        best = max(best, min(k, P))
    return best
